CREATE TABLE keyword_documents(point_uuid TEXT PRIMARY KEY,project_uid TEXT NOT NULL REFERENCES projects,generation_uid TEXT NOT NULL REFERENCES index_generations,item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL REFERENCES item_revisions,chunk_uid TEXT NOT NULL REFERENCES chunks,terms TEXT NOT NULL);
CREATE VIRTUAL TABLE keyword_fts USING fts5(point_uuid UNINDEXED,project_uid UNINDEXED,generation_uid UNINDEXED,terms,tokenize='unicode61');
CREATE INDEX keyword_pair ON keyword_documents(project_uid,generation_uid);
CREATE TABLE generation_configs(generation_uid TEXT PRIMARY KEY REFERENCES index_generations,config_fingerprint TEXT NOT NULL,model_profile TEXT NOT NULL,processing_config TEXT NOT NULL,lexical_version TEXT NOT NULL,collection_name TEXT NOT NULL UNIQUE,cleanup_state TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(cleanup_state IN ('ACTIVE','PENDING','DELETING','DELETED')),expected_refs TEXT NOT NULL);
CREATE TABLE index_publications(generation_uid TEXT NOT NULL REFERENCES index_generations,item_uid TEXT NOT NULL REFERENCES items,result_uid TEXT NOT NULL REFERENCES processing_results,revision_uid TEXT NOT NULL REFERENCES item_revisions,points_digest TEXT NOT NULL,point_count INTEGER NOT NULL CHECK(point_count>=0),dense_evidence TEXT NOT NULL,lexical_digest TEXT NOT NULL,PRIMARY KEY(generation_uid,item_uid));
CREATE TABLE index_snapshots(job_id TEXT PRIMARY KEY REFERENCES jobs(job_id),config_revision TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE index_outcomes(job_id TEXT NOT NULL REFERENCES jobs(job_id),item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL REFERENCES item_revisions,result_uid TEXT REFERENCES processing_results,state TEXT NOT NULL CHECK(state IN ('SUCCEEDED','FAILED')),error_code TEXT,PRIMARY KEY(job_id,item_uid));
CREATE TABLE search_reader_pins(reader_uid TEXT NOT NULL,project_uid TEXT NOT NULL REFERENCES projects,generation_uid TEXT NOT NULL REFERENCES index_generations,created_at REAL NOT NULL,PRIMARY KEY(reader_uid,generation_uid));
CREATE INDEX generation_readers ON search_reader_pins(generation_uid);
CREATE TRIGGER generation_config_immutable BEFORE UPDATE ON generation_configs WHEN NEW.generation_uid!=OLD.generation_uid OR NEW.config_fingerprint!=OLD.config_fingerprint OR NEW.model_profile!=OLD.model_profile OR NEW.processing_config!=OLD.processing_config OR NEW.lexical_version!=OLD.lexical_version OR NEW.collection_name!=OLD.collection_name OR NEW.expected_refs!=OLD.expected_refs BEGIN SELECT RAISE(ABORT,'generation config immutable'); END;
CREATE TRIGGER publication_owner_insert BEFORE INSERT ON index_publications WHEN NOT EXISTS(SELECT 1 FROM processing_results r JOIN index_generations g ON g.project_uid=r.project_uid WHERE r.result_uid=NEW.result_uid AND r.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid AND g.generation_uid=NEW.generation_uid) BEGIN SELECT RAISE(ABORT,'publication ownership mismatch'); END;
CREATE TRIGGER publication_owner_update BEFORE UPDATE ON index_publications WHEN NOT EXISTS(SELECT 1 FROM processing_results r JOIN index_generations g ON g.project_uid=r.project_uid WHERE r.result_uid=NEW.result_uid AND r.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid AND g.generation_uid=NEW.generation_uid) BEGIN SELECT RAISE(ABORT,'publication ownership mismatch'); END;
CREATE TRIGGER reader_owner_insert BEFORE INSERT ON search_reader_pins WHEN NOT EXISTS(SELECT 1 FROM index_generations WHERE generation_uid=NEW.generation_uid AND project_uid=NEW.project_uid) BEGIN SELECT RAISE(ABORT,'reader ownership mismatch'); END;
CREATE TRIGGER keyword_owner_insert BEFORE INSERT ON keyword_documents WHEN NOT EXISTS(SELECT 1 FROM chunks c JOIN item_revisions r USING(revision_uid) JOIN items i USING(item_uid) JOIN index_generations g ON g.project_uid=i.project_uid WHERE c.chunk_uid=NEW.chunk_uid AND c.revision_uid=NEW.revision_uid AND r.item_uid=NEW.item_uid AND i.project_uid=NEW.project_uid AND g.generation_uid=NEW.generation_uid) BEGIN SELECT RAISE(ABORT,'keyword ownership mismatch'); END;
CREATE TRIGGER keyword_owner_update BEFORE UPDATE ON keyword_documents WHEN NEW.point_uuid!=OLD.point_uuid OR NEW.project_uid!=OLD.project_uid OR NEW.generation_uid!=OLD.generation_uid OR NEW.item_uid!=OLD.item_uid OR NEW.revision_uid!=OLD.revision_uid OR NEW.chunk_uid!=OLD.chunk_uid BEGIN SELECT RAISE(ABORT,'keyword ownership immutable'); END;
